b32 main(void)
{
        floor_checksums();
        floor_codebook();
        floor_lzma_span();
        floor_range();
        floor_huffman();
        floor_deflate();
        floor_deflate_codes();
        floor_deflate_tokens();
        floor_huffman_lengths();
        floor_zstd_huffman_cells();
        floor_huffman_codes();
        floor_zstd_fse_cells();
        floor_zstd_huffman_codes();
        return test_report(null);
}
